import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { Text } from "@earendil-works/pi-tui";
import { Type } from "typebox";
import { formatGreeting, type GreetingMode } from "../lib/greeting.ts";
import { StringEnum } from "@earendil-works/pi-ai";

const greetParameters = Type.Object({
  name: Type.String({ description: "Name to greet" }),
  // Pi 1.5.0: outside the Pi host, StringEnum is typed as a pi-schema Schema, which
  // Type.Object cannot infer. Type.Unsafe keeps StringEnum's plain-enum wire schema
  // while giving TypeBox the literal type, so `params.mode` stays a GreetingMode.
  mode: Type.Unsafe<GreetingMode>(
    StringEnum(["short", "friendly"] as const, {
      description: "Greeting style. Prefer short unless the user asks for more warmth.",
    }),
  ),
});

type GreetParams = {
  name: string;
  mode: GreetingMode;
};

function normalizeGreetArgs(args: unknown): GreetParams {
  if (!args || typeof args !== "object") {
    return args as GreetParams;
  }

  const input = args as {
    name?: string;
    mode?: GreetingMode;
    greetingStyle?: GreetingMode;
  };

  if (input.greetingStyle && input.mode === undefined) {
    return { name: input.name ?? "Pi", mode: input.greetingStyle };
  }

  return args as GreetParams;
}

export default function (pi: ExtensionAPI) {
  pi.registerCommand("template-info", {
    description: "Show TypeScript template information",
    handler: async (_args, ctx) => {
      if (ctx.hasUI) {
        ctx.ui.notify("TypeScript-first Pi package template loaded.", "info");
      }
    },
  });

  pi.registerTool({
    name: "template_greet",
    label: "Template Greet",
    description: "Return a typed greeting from the Pi package template",
    promptSnippet: "template_greet: return a typed greeting from the template package",
    promptGuidelines: [
      "Use template_greet only when testing this template package or greeting the user.",
    ],
    parameters: greetParameters,
    prepareArguments: normalizeGreetArgs,
    async execute(_toolCallId, params, signal, _onUpdate, _ctx) {
      if (signal?.aborted) {
        return { content: [{ type: "text", text: "Cancelled" }], details: {} };
      }

      const message = formatGreeting(params);

      return {
        content: [{ type: "text", text: message }],
        details: { message, mode: params.mode },
      };
    },

    renderCall(args, theme, _context) {
      let text = theme.fg("toolTitle", theme.bold("template_greet "));
      text += theme.fg("accent", `name=${args.name}`);
      text += theme.fg("dim", ` mode=${args.mode}`);
      return new Text(text, 0, 0);
    },

    renderResult(result, { expanded }, theme, _context) {
      const details = result.details as { message: string; mode: string } | undefined;
      const content = result.content[0];
      const message =
        details?.message ?? (content?.type === "text" ? content.text : "");

      let text = theme.fg("success", "→ ") + theme.fg("text", message);
      if (expanded && details) {
        text += `\n${theme.fg("dim", `mode: ${details.mode}`)}`;
      }
      return new Text(text, 0, 0);
    },
  });
}

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { formatTable } from "../../lib/format-table.ts";
import { defaultPackageLayoutConfig } from "./lib/config.ts";
import { getPackageResourceRows } from "./lib/stats.ts";

const config = defaultPackageLayoutConfig;

export default function (pi: ExtensionAPI) {
  pi.on("session_start", async (_event, ctx) => {
    if (ctx.hasUI) {
      ctx.ui.setStatus(config.statusLabel, config.title);
    }
  });

  pi.registerCommand("template-layout", {
    description: "Show Pi package resource layout from a multi-file extension",
    handler: async (_args, ctx) => {
      if (!ctx.hasUI) {
        return;
      }

      const rows = getPackageResourceRows();
      const tableLines = formatTable(rows, [
        { header: "Kind", render: (row) => row.kind },
        { header: "Path", render: (row) => row.path },
        { header: "Examples", render: (row) => row.examples },
      ]);

      const widgetLines = [config.title, "", ...tableLines];
      if (config.showSkillHint) {
        widgetLines.push("", "Skills: static skills/ dir + extensions/skill-bridge via resources_discover");
      }

      ctx.ui.setWidget("template-layout", widgetLines, { placement: "belowEditor" });
      ctx.ui.notify("Package layout shown below the editor. Clear with /template-layout-clear.", "info");
    },
  });

  pi.registerCommand("template-layout-clear", {
    description: "Clear the package layout widget",
    handler: async (_args, ctx) => {
      if (!ctx.hasUI) {
        return;
      }

      ctx.ui.setWidget("template-layout", undefined);
    },
  });
}

import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

const baseDir = dirname(fileURLToPath(import.meta.url));

export default function (pi: ExtensionAPI) {
  pi.on("resources_discover", () => ({
    skillPaths: [join(baseDir, "SKILL.md")],
  }));

  pi.registerCommand("template-skill-info", {
    description: "Explain how this extension contributes an Agent Skill",
    handler: async (_args, ctx) => {
      if (!ctx.hasUI) {
        return;
      }

      ctx.ui.notify(
        "Skill bridge active. Try /skill:template-skill-bridge or ask the agent to use the template skill.",
        "info",
      );
    },
  });
}

#!/usr/bin/env node

import { readFileSync } from "node:fs";
import { cwd } from "node:process";
import { collectProjectOptions } from "./prompts.mjs";
import {
  assertOutputDirectoryAvailable,
  cleanupBootstrapDocs,
  resolveOutputDirectory,
  runPostSetup,
  scaffoldProject,
} from "./scaffold.mjs";
import { getGitConfig, parsePackageArg, resolveOwnerSlug } from "./utils.mjs";

function printHelp(write = console.log) {
  write(`Usage: create-pi-extension [options] <package-name>

Scaffold a new Pi extension project.

Examples:
  bunx create-pi-extension my-pi-package
  bunx create-pi-extension @my-scope/my-pi-tool

Options:
  -v, --version                       Print the CLI version
  -y, --yes                           Use defaults without prompts
  -h, --help                          Show this help

Environment:
  CREATE_PI_EXTENSION_YES=1           Use defaults without prompts
  CREATE_PI_EXTENSION_SKIP_POST_SETUP=1   Skip git init and bun install
`);
}

async function main() {
  let packageNameArg;
  let showHelp = false;
  let showVersion = false;
  let useDefaults = false;

  for (const arg of process.argv.slice(2)) {
    if (arg === "-h" || arg === "--help") {
      showHelp = true;
    } else if (arg === "-v" || arg === "--version") {
      showVersion = true;
    } else if (arg === "-y" || arg === "--yes") {
      useDefaults = true;
    } else if (arg.startsWith("-")) {
      console.error(`Unknown option: ${arg}`);
      printHelp(console.error);
      process.exitCode = 1;
      return;
    } else if (packageNameArg === undefined) {
      packageNameArg = arg;
    } else {
      console.error(`Unexpected argument: ${arg}`);
      printHelp(console.error);
      process.exitCode = 1;
      return;
    }
  }

  if (showVersion) {
    const packageJson = JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf8"));
    console.log(packageJson.version);
    return;
  }

  if (showHelp || !packageNameArg) {
    printHelp();
    if (!showHelp) {
      process.exitCode = 1;
    }
    return;
  }

  if (useDefaults) {
    process.env.CREATE_PI_EXTENSION_YES = "1";
  }

  const { packageName, directoryName } = parsePackageArg(packageNameArg);
  const outputDir = resolveOutputDirectory(cwd(), directoryName);
  assertOutputDirectoryAvailable(outputDir);

  const ownerSlug = resolveOwnerSlug("your-name");

  const defaults = {
    displayName: directoryName,
    description: `Pi package ${packageName}`,
    author:
      process.env.CREATE_PI_EXTENSION_AUTHOR?.trim() ||
      getGitConfig("user.name") ||
      "Pi Developer",
    owner: ownerSlug,
    ownerRepo: `${ownerSlug}/${directoryName}`,
    licenseYear: new Date().getFullYear(),
  };

  const options = await collectProjectOptions({
    packageName,
    directoryName,
    defaults,
  });

  scaffoldProject(outputDir, options);
  const removedDocs = cleanupBootstrapDocs(outputDir);
  runPostSetup(outputDir);

  if (removedDocs.length > 0) {
    console.log("\nRemoved bootstrap docs:");
    for (const doc of removedDocs) {
      console.log(`  - ${doc}`);
    }
  }

  console.log("\nNext steps:");
  console.log(`  1. Enter the project directory: cd ${directoryName}`);
  console.log("  2. Edit extensions/");
  console.log("  3. Run bun run ci");
  console.log("  4. Try pi -e .");
  console.log(`\nCreated ${packageName} at ${outputDir}`);
}

main().catch((error) => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exit(1);
});
